// POST daily-message failed for one or more students. The other students are unaffected.
// Recover which student each error belongs to through n8n's item pairing.
const src = $('Split Out students').all();
const out = [];
$input.all().forEach((it, i) => {
  const idx = (it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : i;
  const s = (src[idx] && src[idx].json) || {};
  const raw = (it.json && it.json.error !== undefined) ? it.json.error : it.json;
  const msg = (typeof raw === 'string') ? raw : ((raw && raw.message) ? raw.message : JSON.stringify(raw));
  const sid = (s.student_id !== undefined) ? s.student_id : null;
  if (sid === null) return;            // cannot attribute to a student -> nothing to record
  out.push({ json: { action: 'error', student_id: sid,
                     email: (s.email !== undefined) ? s.email : null,
                     delivered: false, error: ('daily-message failed: ' + String(msg)).slice(0, 300) } });
});
return out;

// Runs once after ALL student Gmail sends. Folds the outcomes into ONE daily-result item per student.
// Sends are sequential and one-output-per-input, so output i belongs to the i-th student item of
// 'Prepare Gmail messages' (pairedItem is used when n8n provides it).
const plan = $('Prepare Gmail messages').all().map((i) => i.json).filter((j) => j.route === 'student');
const outs = $input.all();
const result = [];
outs.forEach((o, i) => {
  const idx = (o.pairedItem && typeof o.pairedItem.item === 'number') ? o.pairedItem.item : i;
  const p = plan[idx];
  if (!p || p.student_id === null || p.student_id === undefined) return;
  const j = o.json || {};
  const failed = (j.error !== undefined && j.error !== null && j.error !== false);
  let error = null;
  if (failed) {
    const raw = j.error;
    const m = (typeof raw === 'string') ? raw : ((raw && raw.message) ? raw.message : JSON.stringify(raw));
    error = ('gmail send failed: ' + m).slice(0, 300);
  }
  result.push({ json: { student_id: p.student_id, delivered: !failed, error } });
});
return result;

// Students for whom there was nothing deliverable (no email / no body / unexpected kind).
// Recorded as a failed attempt so the API's own retry limit and admin alert apply instead of silently looping forever.
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.route !== 'skip' || j.student_id === null || j.student_id === undefined) continue;
  out.push({ json: { student_id: j.student_id, delivered: false, error: ('not delivered: ' + String(j.reason)).slice(0, 300) } });
}
return out;

// Response of daily-result: {ok, admin_alert}. FastAPI sets admin_alert when a student reaches the max failures for today.
const admin = String($env.ADMIN_EMAIL || '').trim();
if (!admin) return [];
const out = [];
let recordFailures = 0, firstErr = null;
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error !== undefined && j.error !== null) {
    recordFailures += 1;
    if (firstErr === null) firstErr = (typeof j.error === 'string') ? j.error : ((j.error && j.error.message) ? j.error.message : JSON.stringify(j.error));
  } else if (j.admin_alert) {
    out.push({ json: { to: admin, subject: '[Tutor] Daily lesson alert', body: String(j.admin_alert).slice(0, 3500) } });
  }
}
if (recordFailures > 0) {
  out.push({ json: { to: admin, subject: '[Tutor] daily-result could not be recorded',
    body: 'daily-result could not be recorded for ' + recordFailures + ' student(s).\nerror: ' + String(firstErr).slice(0, 300) +
          '\nThose students may receive today\'s message again.' } });
}
return out;

// One item per incoming Gmail message (full format: parsed headers + text body).
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  let sender = '';
  if (j.from && Array.isArray(j.from.value) && j.from.value[0]) sender = j.from.value[0].address || '';
  if (!sender) { const f = j.From || j.from || j.sender; sender = (typeof f === 'string') ? f : ((f && f.text) ? f.text : ''); }
  const body = (typeof j.text === 'string' && j.text.trim()) ? j.text : ((typeof j.snippet === 'string') ? j.snippet : '');
  out.push({ json: {
    sender: String(sender),
    message_id: String(j.messageId || j.id || '').trim(),   // RFC Message-ID, else Gmail id: used by FastAPI for de-duplication
    gmail_id: j.id || null,                                  // Gmail id: needed to reply in the same thread
    thread_id: j.threadId || null,
    subject: String(j.subject || j.Subject || ''),
    body,
  } });
}
return out;

// FastAPI /email/incoming answer -> ready-to-send Gmail items (plain text, no HTML).
const r = $input.first().json || {};
let src = {};
try { src = $('Loop Over Emails').first().json || {}; } catch (e) {}
const KNOWN = ['PASS', 'RETRY', 'WEAK', 'MASTERED', 'LESSON_DONE', 'FINISHED', 'COMMAND', 'BAD_INPUT', 'UNKNOWN_USER', 'ERROR', 'DUPLICATE', 'IGNORED'];
const admin = String($env.ADMIN_EMAIL || '').trim();
const out = [];

// DUPLICATE / IGNORED come back with send=false: nothing is emailed.
if (r.send === true && r.to && r.body && src.gmail_id) {
  out.push({ json: { kind: 'reply', gmail_id: src.gmail_id, to: r.to, subject: r.subject, body: String(r.body).slice(0, 20000), outcome: r.outcome } });
}
let alert = r.admin_alert;
if (!KNOWN.includes(r.outcome)) alert = 'Unexpected outcome from FastAPI: ' + String(r.outcome) + (alert ? ' | ' + alert : '');
if (alert && admin) {
  out.push({ json: { kind: 'alert', to: admin, subject: '[Tutor] ' + String(r.outcome || 'alert'), body: String(alert).slice(0, 3500), outcome: r.outcome } });
}
if (out.length === 0) out.push({ json: { kind: 'none', outcome: r.outcome } });
return out;

// Runs once per email after all sends. Emits ONE item: failed or not.
const items = $input.all();
const failed = items.filter((i) => i.json && i.json.error);
const admin = String($env.ADMIN_EMAIL || '').trim();
if (failed.length === 0 || !admin) return [{ json: { failed: false } }];
let who = '?', subj = '';
try { const s = $('Loop Over Emails').first().json; who = s.sender; subj = s.subject; } catch (e) {}
const raw = failed[0].json.error;
const msg = (typeof raw === 'string') ? raw : ((raw && raw.message) ? raw.message : JSON.stringify(raw));
const body = 'Gmail could not send a reply.\n' +
  'student email: ' + who + '\nsubject: ' + subj + '\n' +
  'failed sends: ' + failed.length + ' of ' + items.length + '\n' +
  'error: ' + String(msg).slice(0, 300) + '\n' +
  'The email was already recorded, so the student may need to write again.';
return [{ json: { failed: true, to: admin, subject: '[Tutor] Gmail delivery failed', body } }];

// POST /email/incoming failed (FastAPI down?). Gmail's trigger will NOT hand this email over again,
// so the alert names the sender; that student must write again once FastAPI is back.
const admin = String($env.ADMIN_EMAIL || '').trim();
if (!admin) return [{ json: { send: false } }];
const store = $getWorkflowStaticData('global');            // at most one such alert per 10 minutes
const now = Date.now();
if (store.lastApiFailAlert && now - store.lastApiFailAlert < 10 * 60 * 1000) return [{ json: { send: false } }];
store.lastApiFailAlert = now;
let who = '?', subj = '';
try { const s = $('Loop Over Emails').first().json; who = s.sender; subj = s.subject; } catch (e) {}
const j = $input.first().json || {};
const raw = (j.error !== undefined) ? j.error : j;
const msg = (typeof raw === 'string') ? raw : ((raw && raw.message) ? raw.message : JSON.stringify(raw));
const body = 'The request to FastAPI /email/incoming failed.\n' +
  'from: ' + who + '\nsubject: ' + subj + '\n' +
  'error: ' + String(msg).slice(0, 300) + '\n' +
  'This email was not graded. Check that FastAPI is running (python -m app serve) and ask the student to write again.';
return [{ json: { send: true, to: admin, subject: '[Tutor] FastAPI request failed', body } }];

// One FastAPI daily-message response per student -> ONE ready-to-send Gmail item (NOT sent yet).
// Output item shapes (every item carries student_id so later steps can report per student):
//   { route:'student', action:'send', student_id, kind, to, subject, body }
//   { route:'admin',   action:'send', student_id, kind:'ADMIN_ALERT', to, subject, body }
//   { route:'skip',    action:'skip', student_id, kind, reason }
const admin = String($env.ADMIN_EMAIL || '').trim();
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const sid = (r.student_id !== undefined) ? r.student_id : null;
  const kind = (typeof r.kind === 'string') ? r.kind : null;
  let reason = null;
  if (kind === 'NONE') reason = 'nothing to send (no current lesson or student has no email address)';
  else if (kind !== 'LESSON' && kind !== 'REMINDER') reason = 'unexpected kind: ' + String(kind);
  else if (!r.email) reason = 'no email address';
  else if (!r.body || !String(r.body).trim()) reason = 'no message body';
  if (reason) {
    out.push({ json: { route: 'skip', action: 'skip', student_id: sid, kind, reason } });
  } else {
    out.push({ json: { route: 'student', action: 'send', student_id: sid, kind, to: r.email,
                       subject: String(r.subject || 'Python lesson').slice(0, 200), body: String(r.body).slice(0, 20000) } });
  }
  // FastAPI may attach an admin alert (e.g. "student has not replied for N days").
  if (r.admin_alert && admin) {
    out.push({ json: { route: 'admin', action: 'send', student_id: sid, kind: 'ADMIN_ALERT', to: admin,
                       subject: '[Tutor] Student alert', body: String(r.admin_alert).slice(0, 3500) } });
  }
}
return out;
